export const getListDocumentCommentsUrl = (documentId: string,
    params?: ListDocumentCommentsParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/documents/${documentId}/comments?${stringifiedParams}` : `/api/documents/${documentId}/comments`
}

